// CodeRaksh Morning Radar Compiler
const today = $now.toISODate();
const num = (v) => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const safeRows = (nodeName) => {
  try { return $(nodeName).all().map(i => i.json).filter(r => Object.keys(r).length); }
  catch(e) { return []; }
};

const bookings = safeRows('Morning - Read Bookings').filter(r => String(r.Start || r.Date || '').startsWith(today));
const allLeads = safeRows('Morning - Read Leads');
const hotLeads = allLeads.filter(r => String(r.Status || '').toLowerCase() === 'hot');
const invoices = safeRows('Morning - Read Invoices');
const unpaidInvoices = invoices.filter(r => String(r.Status || '').toLowerCase() !== 'paid');
const overdueInvoices = unpaidInvoices.filter(r => r['Due date'] && String(r['Due date']) < today);
const dueTodayInvoices = unpaidInvoices.filter(r => r['Due date'] && String(r['Due date']).startsWith(today));

const deadlines = safeRows('Morning - Read Deadlines');
const urgentDeadlines = deadlines.filter(r => {
  if (!r['Due date']) return false;
  const d = String(r['Due date']);
  return d >= today && d <= $now.plus({ days: 3 }).toISODate();
});

const pendingDocs = safeRows('Morning - Read Pending Docs');
const urgentDocs = pendingDocs.filter(r => String(r.Status || '').toLowerCase() === 'pending' && num(r.Reminders) >= 2);

return [{
  json: {
    today_date: today,
    company: "CodeRaksh Company",
    radar: {
      todays_meetings_count: bookings.length,
      todays_meetings: bookings.map(b => `${b.Name || 'Client'} at ${b.Start || b.Time || 'TBD'}`),
      hot_leads_pending_count: hotLeads.length,
      hot_leads: hotLeads.slice(0, 5).map(l => `${l.Name || 'Lead'} (${l.Phone || l.Email || 'No contact'}) - ${l.Source || 'Website'}`),
      overdue_invoices_count: overdueInvoices.length,
      overdue_amount_total: overdueInvoices.reduce((acc, curr) => acc + num(curr.Amount), 0),
      due_today_count: dueTodayInvoices.length,
      due_today_amount: dueTodayInvoices.reduce((acc, curr) => acc + num(curr.Amount), 0),
      urgent_deadlines_3days: urgentDeadlines.map(d => `${d.Filing || d.Task || 'Deadline'} due ${d['Due date']}`),
      urgent_pending_docs_count: urgentDocs.length,
      urgent_docs_list: urgentDocs.map(d => `${d.Client || 'Client'}: missing ${d.Document || 'Docs'}`)
    }
  }
}];

// CodeRaksh 20-Agent Performance Matrix & Enterprise Health Score Engine
const today = $now.toISODate();
const num = (v) => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const safeRows = (nodeName) => {
  try { return $(nodeName).all().map(i => i.json).filter(r => Object.keys(r).length); }
  catch(e) { return []; }
};
const isToday = (r) => {
  const d = String(r.Date || r.Timestamp || r['Created Date'] || r.Asked_on || '');
  return d.startsWith(today);
};

// 1. SALES DEPT (01-04)
const allLeads = safeRows('Nightly - Read Leads');
const leadsToday = allLeads.filter(isToday);
const hotLeads = leadsToday.filter(r => String(r.Status || '').toLowerCase() === 'hot');
const warmLeads = leadsToday.filter(r => String(r.Status || '').toLowerCase() === 'warm');
const ordersToday = safeRows('Nightly - Read Orders').filter(isToday);
const repeatOrderRevenue = ordersToday.reduce((s, r) => s + num(r.Amount || r.Total), 0);

// 2. SUPPORT DEPT (05-08)
const bookingsToday = safeRows('Nightly - Read Bookings').filter(isToday);
const reviewsAll = safeRows('Nightly - Read Reviews');
const reviewsToday = reviewsAll.filter(isToday);
const angryReviews = reviewsToday.filter(r => String(r.Sentiment || '').toLowerCase() === 'angry' || num(r.Stars) <= 2);
const fiveStarReviews = reviewsToday.filter(r => num(r.Stars) >= 4);

// 3. MARKETING DEPT (09-12)
const contentToday = safeRows('Nightly - Read Content').filter(isToday);
const contentCount = contentToday.length;

// 4. FINANCE DEPT (13-16)
const billsToday = safeRows('Nightly - Read Bills').filter(isToday);
const totalBillsAmount = billsToday.reduce((s, r) => s + num(r.amount || r.Amount), 0);
const invoicesAll = safeRows('Nightly - Read Invoices');
const invoicesToday = invoicesAll.filter(isToday);
const paidToday = invoicesToday.filter(r => String(r.Status || '').toLowerCase() === 'paid');
const revenueToday = paidToday.reduce((s, r) => s + num(r.Amount), 0);
const overdueInvoices = invoicesAll.filter(r => String(r.Status || '').toLowerCase() !== 'paid' && r['Due date'] && String(r['Due date']) < today);
const totalOverdue = overdueInvoices.reduce((s, r) => s + num(r.Amount), 0);
const gstPurchasesToday = safeRows('Nightly - Read GST Purchases').filter(isToday);
const itcTotalToday = gstPurchasesToday.reduce((s, r) => s + num(r.CGST) + num(r.SGST) + num(r.IGST), 0);

// 5. OPS DEPT (17-20)
const candidatesToday = safeRows('Nightly - Read Candidates').filter(isToday);
const shortlistedCands = candidatesToday.filter(r => String(r.Status || '').toLowerCase() === 'shortlist');
const deadlinesAll = safeRows('Nightly - Read Deadlines');
const pendingDeadlines7Days = deadlinesAll.filter(r => {
  if (!r['Due date']) return false;
  const d = String(r['Due date']);
  return d >= today && d <= $now.plus({ days: 7 }).toISODate();
});
const pendingDocsAll = safeRows('Nightly - Read Pending Docs');
const severeDocBottlenecks = pendingDocsAll.filter(r => String(r.Status || '').toLowerCase() === 'pending' && num(r.Reminders) >= 3);

// ==========================================
// MATHEMATICAL COMPANY HEALTH SCORE (0 - 100)
// ==========================================
// Sub-score 1: Finance (Max 30) - penalize heavy overdue relative to revenue
let financeScore = 25;
if (totalOverdue > 100000) financeScore -= 10;
else if (totalOverdue > 30000) financeScore -= 5;
if (revenueToday > totalBillsAmount) financeScore += 5;
financeScore = Math.max(5, Math.min(30, financeScore));

// Sub-score 2: Sales Pipeline (Max 25)
let salesScore = 15;
if (hotLeads.length >= 2) salesScore += 10;
else if (leadsToday.length > 0) salesScore += 5;
if (ordersToday.length > 0) salesScore += 5;
salesScore = Math.min(25, salesScore);

// Sub-score 3: Customer Satisfaction (Max 20)
let supportScore = 18;
if (angryReviews.length > 0) supportScore -= 10 * angryReviews.length;
if (fiveStarReviews.length > 0) supportScore += 2 * fiveStarReviews.length;
supportScore = Math.max(0, Math.min(20, supportScore));

// Sub-score 4: Operational Execution (Max 25)
let opsScore = 22;
if (pendingDeadlines7Days.length > 5) opsScore -= 5;
if (severeDocBottlenecks.length > 2) opsScore -= 5;
if (shortlistedCands.length > 0) opsScore += 3;
opsScore = Math.max(5, Math.min(25, opsScore));

const totalHealthScore = Math.round(financeScore + salesScore + supportScore + opsScore);
let healthGrade = '🟢 HEALTHY';
if (totalHealthScore < 60) healthGrade = '🔴 CRITICAL ACTION REQUIRED';
else if (totalHealthScore < 80) healthGrade = '🟡 ATTENTION NEEDED';

return [{
  json: {
    date: today,
    company: "CodeRaksh Company",
    health_score: totalHealthScore,
    health_grade: healthGrade,
    department_breakdown: {
      sales: {
        new_leads_count: leadsToday.length,
        hot_leads_count: hotLeads.length,
        warm_leads_count: warmLeads.length,
        hot_lead_names: hotLeads.map(l => `${l.Name || 'Lead'} (${l.Source || 'Direct'})`),
        repeat_orders_count: ordersToday.length,
        repeat_revenue: repeatOrderRevenue
      },
      support: {
        bookings_today: bookingsToday.length,
        reviews_count: reviewsToday.length,
        five_star_reviews: fiveStarReviews.length,
        angry_reviews: angryReviews.map(r => `${r.Reviewer || 'Customer'}: ${r.Stars}★ "${r.Comment || ''}"`)
      },
      marketing: {
        pieces_published: contentCount,
        content_titles: contentToday.map(c => `${c.Type || 'Post'}: ${c.Title || ''}`)
      },
      finance: {
        revenue_collected_today: revenueToday,
        bills_processed_today: billsToday.length,
        bills_amount_today: totalBillsAmount,
        overdue_invoices_count: overdueInvoices.length,
        total_overdue_amount: totalOverdue,
        gst_itc_claimed_today: itcTotalToday
      },
      ops: {
        candidates_screened: candidatesToday.length,
        candidates_shortlisted: shortlistedCands.map(c => `${c.Name} (${c.Score}/10)`),
        upcoming_deadlines_7days: pendingDeadlines7Days.map(d => `${d.Filing || d.Task} (${d['Due date']})`),
        critical_doc_chases: severeDocBottlenecks.map(b => `${b.Client}: ${b.Document}`)
      }
    }
  }
}];

// Prep Context for Interactive CEO Brain
const query = $('CEO Command Webhook').first().json.body?.query || $('CEO Command Webhook').first().json.query || 'Company summary';
const sender = $('CEO Command Webhook').first().json.body?.sender || 'Founder';

const logs = $('Interactive - Read Latest Log').all().map(i => i.json);
const invoices = $('Interactive - Read Invoices').all().map(i => i.json);
const unpaid = invoices.filter(r => String(r.Status || '').toLowerCase() !== 'paid');

return [{
  json: {
    user_query: query,
    sender: sender,
    latest_daily_log: logs.slice(-1)[0] || {},
    unpaid_invoices_count: unpaid.length,
    unpaid_invoices_sample: unpaid.slice(0, 5)
  }
}];

