// CodeRaksh Anomaly Watchdog Triage
const body = $json.body || $json;
const eventType = body.event_type || body.type || 'UNKNOWN_ALERT';
const message = body.message || body.details || JSON.stringify(body);
const severity = body.severity || 'HIGH'; // CRITICAL, HIGH, MEDIUM

return [{
  json: {
    event_type: eventType,
    severity: severity,
    message: message,
    timestamp: $now.toFormat('dd LLL yyyy, HH:mm:ss'),
    contact_name: body.name || body.client || 'Unknown',
    contact_phone: body.phone || 'N/A'
  }
}];

